changeSet.sql:
create or alter procedure [api].[ParseAssetPaths] as begin set nocount on; declare @IsBussOrTechClass bit = 0;
-- Comes from higher-level procedure --#tbl ( GroupID bigint, AssetTypeID int, ID bigint, [Level] int, [Position] decimal(5,3), ParentID bigint, ParentLevel int, ParentPosition decimal(5,3), ColumnOrder int, FormattedValue nvarchar(max) )
drop table if exists #tblgrp drop table if exists #illegalxml
if exists (select 1 from #tbl t inner join AssetType att on att.id = t.assetTypeId and att.class in (1,8)) begin set @IsBussOrTechClass = 1; end
if exists (select 1 from #tbl where [Level] < 1) begin drop table if exists #temptbl;
select GroupID,abs(min([Level]))+1 [LevelUp] into #temptbl from #tbl group by GroupID;
create clustered index cx_temptbl on #temptbl(GroupID);
update T set [Level] = [Level] + S.[LevelUp], [ParentLevel] = [ParentLevel] + S.[LevelUp] from #tbl T inner join #temptbl S on S.GroupID = T.GroupID
drop table if exists #temptbl; end
create table #tblgrp (GroupId bigint,XMLData NVARCHAR(max) NULL,KeyPathHash nvarchar(32)) create clustered index CIX_tblgrp on #tblgrp (GroupID)
insert into #tblgrp (GroupId, XMLData) select s.groupid,(select t.[Level] as '@level', t.ColumnOrder as '@position', t.AssetTypeID as '@assetTypeId', t.ID as '@assetId', t.FormattedValue as 'data()' from #tbl t where t.GroupID = S.GroupID order by t.Position for xml path('segment'), root('path')) XMLData from #tbl s group by s.groupid;
--The XML parser throws an 'illegal xml character' error when converting #tblgrp.XMLData to AssetNode.Segments --if XMLData contains escaped ASCII control characters such as Bell(x07), Device Control 3(x13) or File Seperator (x1C) --These characters should be rare, so only execute if the XMLData contains an encoded two digit hex value if exists (select 1 from #tblgrp where patindex('%&#x__;%', XMLData) > 0) begin create table #illegalxml ( Escaped NVARCHAR(6) );
WITH controlRange(V) AS ( SELECT 0 UNION ALL SELECT V + 1FROM controlRange WHERE V < 31 ) INSERT into #illegalxml (Escaped) SELECT '&#x'+RIGHT('00'+FORMAT(V, 'X'), 2)+';' FROM controlRange WHERE V NOT IN (9, 10, 13) --TAB, LF, CR
declare @replacePattern nvarchar(6) = null
set @replacePattern = ( select top 1 x.Escaped from #tblgrp t cross join #illegalxml x where charindex(x.Escaped, t.XMLData) > 0 )
while @replacePattern is not null begin update #tblgrp set XMLData = REPLACE(XMLData, @replacePattern, '') where patindex('%&#x__;%', XMLData) > 0;
set @replacePattern = ( select top 1 x.Escaped from #tblgrp t cross join #illegalxml x where charindex(x.Escaped, t.XMLData) > 0 ); end end
if exists (select 1 from AssetPath t inner join #tblgrp s on t.Id = s.GroupId) begin update g set KeyPathHash = ([dbo].[GetKeyPathHash]([XmlData])) from #tblgrp g;
merge AssetPath as t using ( select GroupId as Id, XmlData as Segments, KeyPathHash from #tblgrp ) as s on (t.Id = s.Id) when matched and t.KeyPathHash != s.KeyPathHash then update set t.Segments = s.Segments when not matched by target then insert (Id, Segments) values (s.Id, s.Segments);
if (@IsBussOrTechClass = 1) begin drop table if exists #tbldtl;
create table #tbldtl(AssetId bigint,AssetTypeID int,LevelAssetIDMax bigint, LevelMax int,FormattedValue nvarchar(4000)) create clustered index cx_tbldtl on #tbldtl(AssetId,assetTypeId);
insert into #tbldtl(AssetId,assetTypeId,LevelAssetIDMax,LevelMax,FormattedValue) select t.GroupID,t.AssetTypeID,max(t.ID), max(t.[Level]), substring(string_agg(t.FormattedValue, ' / ') within group(order by t.ColumnOrder),1,4000) FormattedValue from #tbl t group by t.GroupID,t.AssetTypeID ;
delete s from #tbldtl s inner join [dbo].[AssetPathSegmentDtl] t on (t.AssetId = s.AssetId and t.AssetTypeID = s.AssetTypeID ) where t.LevelAssetIDMax = s.LevelAssetIDMax and t.LevelMax = s.LevelMax and t.FormattedValue = s.FormattedValue;
merge [dbo].[AssetPathSegmentDtl] as t using ( select * from #tbldtl ) as s on (t.AssetId = s.AssetId and t.AssetTypeID = s.AssetTypeID ) when matched then update set t.FormattedValue = s.FormattedValue, t.LevelAssetIDMax = s.LevelAssetIDMax, t.LevelMax = s.LevelMax when not matched by target then insert (AssetId,assetTypeId,LevelMax,FormattedValue) values (s.AssetId, s.assetTypeId,s.LevelMax,s.FormattedValue);
drop table if exists #tbldtl; end end else begin insert into AssetPath (Id, Segments) select S.GroupId as Id,S.XmlData as Segments from #tblgrp s;
if (@IsBussOrTechClass = 1) begin insert into [dbo].[AssetPathSegmentDtl] ([AssetID],[AssetTypeID],LevelAssetIDMax,[LevelMax],FormattedValue ) select t.GroupID,t.AssetTypeID, max(t.ID), max(t.[Level]), substring(string_agg(t.FormattedValue, ' / ') within group(order by t.ColumnOrder),1,4000) FormattedValue from #tbl t left join [dbo].[AssetPathSegmentDtl] s on (t.AssetId = s.AssetId and t.AssetTypeID = s.AssetTypeID ) where [dbo].[AssetPathSegmentDtl] is null group by t.GroupID,t.AssetTypeID end end
drop table if exists #tbldtl; drop table if exists #tblgrp drop table if exists #illegalxml end
